import csv, codecs
path='/tmp/weoapr2025all.xls'
with codecs.open(path,'r','utf-16-le') as f:
    reader=csv.reader(f, delimiter='\t')
    header=next(reader)
    year_cols={int(y):header.index(str(y)) for y in range(2020,2028)}
    data={}
    for row in reader:
        if len(row)<10: continue
        if row[3]=='Georgia' and row[2] in ('NGDP_R','NGDP_RPCH','NGDP_D','NGDP','NGDPD'):
            code=row[2]
            vals={y: row[idx] for y, idx in year_cols.items()}
            data[code]=vals
    print(data)
PY"}

